import { test } from "node:test";
import assert from "node:assert/strict";
import { createInventory } from "../src/warehouse/inventory.js";
import { reserveOrder } from "../src/warehouse/reserve.js";
import { fulfilOrder } from "../src/warehouse/fulfil.js";
import { fulfilAll, describe } from "../src/warehouse/batch.js";

function fakeShipper() {
  const shipped = [];
  return {
    shipped,
    async ship(orderId, holds) {
      shipped.push({ orderId, holds });
      return `TRK-${orderId}`;
    },
  };
}

const sorted = (holds) => [...holds].sort((a, b) => a.sku.localeCompare(b.sku));

test("reserveOrder returns every hold once the call resolves", async () => {
  const inv = createInventory({ A: 5, B: 5, C: 5 });
  const res = await reserveOrder(inv, [
    { sku: "A", qty: 2 },
    { sku: "B", qty: 1 },
    { sku: "C", qty: 5 },
  ]);
  assert.deepEqual(sorted(res.reserved), [
    { sku: "A", qty: 2 },
    { sku: "B", qty: 1 },
    { sku: "C", qty: 5 },
  ]);
  assert.deepEqual(res.failed, []);
});

test("stock is already decremented when reserveOrder resolves", async () => {
  const inv = createInventory({ A: 5, B: 3 });
  await reserveOrder(inv, [
    { sku: "A", qty: 2 },
    { sku: "B", qty: 3 },
  ]);
  console.log("available after reserveOrder:", { A: inv.available("A"), B: inv.available("B") });
  assert.equal(inv.available("A"), 3, "A should be reserved before the call returns");
  assert.equal(inv.available("B"), 0, "B should be reserved before the call returns");
});

test("out-of-stock lines are reported in failed", async () => {
  const inv = createInventory({ A: 5, B: 0 });
  const res = await reserveOrder(inv, [
    { sku: "A", qty: 1 },
    { sku: "B", qty: 1 },
  ]);
  assert.deepEqual(
    res.failed.map((f) => f.sku),
    ["B"],
  );
  assert.deepEqual(res.reserved, [{ sku: "A", qty: 1 }]);
});

test("an empty order reserves nothing", async () => {
  const inv = createInventory({ A: 1 });
  assert.deepEqual(await reserveOrder(inv, []), { reserved: [], failed: [] });
});

test("fulfilOrder ships the reserved items", async () => {
  const inv = createInventory({ A: 4, B: 4 });
  const shipper = fakeShipper();
  const order = {
    id: "o1",
    lines: [
      { sku: "A", qty: 1 },
      { sku: "B", qty: 2 },
    ],
  };
  const res = await fulfilOrder(inv, order, shipper);
  assert.equal(res.status, "shipped");
  assert.equal(res.picked, 2);
  assert.equal(shipper.shipped[0].holds.length, 2, "the shipment must carry the holds");
});

test("a partially available order is backordered and its stock released", async () => {
  const inv = createInventory({ A: 4, B: 0 });
  const shipper = fakeShipper();
  const order = {
    id: "o2",
    lines: [
      { sku: "A", qty: 3 },
      { sku: "B", qty: 1 },
    ],
  };
  const res = await fulfilOrder(inv, order, shipper);
  assert.equal(res.status, "backordered");
  assert.deepEqual(res.missing, ["B"]);
  assert.equal(shipper.shipped.length, 0);
  assert.equal(inv.available("A"), 4, "A must be released back");
});

test("fulfilAll processes orders against the remaining stock", async () => {
  const inv = createInventory({ A: 3 });
  const shipper = fakeShipper();
  const summary = await fulfilAll(
    inv,
    [
      { id: "o1", lines: [{ sku: "A", qty: 2 }] },
      { id: "o2", lines: [{ sku: "A", qty: 2 }] },
    ],
    shipper,
  );
  assert.equal(summary.shipped, 1);
  assert.equal(summary.backordered, 1);
  assert.match(describe(summary), /o2: backordered \[A\]/);
});
